import { appendFileSync, readFileSync } from "node:fs";
const COMMENT_MARKER = "<!-- auraone-evalkit-action-summary -->";
const MAX_REPORT_CHARS = 30_000;
export function buildComment(summary) {
    const decision = decisionLabel(summary.state);
    const evidence = [
        `| Decision | **${decision}** |`,
        `| Average score | ${formatScore(summary.averageScore)} |`,
        `| Required threshold | ${formatScore(summary.threshold)} |`,
        `| Rubric | \`${escapeInlineCode(summary.rubricPath)}\` |`,
        `| Responses | \`${escapeInlineCode(summary.responsesPath)}\` |`,
    ];
    const details = summary.report?.trim()
        ? ["", "### Evidence", "", sanitizeReport(summary.report)]
        : summary.error
            ? ["", "### Evidence", "", escapeMarkdown(summary.error)]
            : [];
    return [
        COMMENT_MARKER,
        "## AuraOne EvalKit",
        "",
        `**Decision:** ${decision}`,
        "",
        "| Evidence | Result |",
        "| --- | --- |",
        ...evidence,
        ...details,
        "",
        "### Next action",
        "",
        nextAction(summary.state),
        "",
        `Generated by AuraOne EvalKit Action ${escapeMarkdown(summary.version)}. Evaluation runs in this workflow using repository-provided inputs.`,
        "",
    ].join("\n");
}
export function emitAnnotation(level, title, message, file) {
    const properties = [`title=${escapeWorkflowProperty(title)}`];
    if (file)
        properties.push(`file=${escapeWorkflowProperty(file)}`);
    console.log(`::${level} ${properties.join(",")}::${escapeWorkflowData(message)}`);
}
export function writeJobSummary(markdown, env = process.env) {
    const path = env.GITHUB_STEP_SUMMARY;
    if (!path)
        return "skipped";
    appendFileSync(path, `${markdown.replace(COMMENT_MARKER, "").trim()}\n`, "utf8");
    return "written";
}
export function writeOutput(name, value, env = process.env) {
    const path = env.GITHUB_OUTPUT;
    if (!path)
        return "skipped";
    const delimiter = `AURAONE_${name.toUpperCase()}_${process.pid}`;
    appendFileSync(path, `${name}<<${delimiter}\n${value}\n${delimiter}\n`, "utf8");
    return "written";
}
export async function postPullRequestComment(body, env = process.env, fetchImpl = fetch) {
    const token = env["INPUT_GITHUB-TOKEN"] || env.GITHUB_TOKEN;
    const repository = env.GITHUB_REPOSITORY;
    const eventPath = env.GITHUB_EVENT_PATH;
    if (!token || !repository || !eventPath || env["INPUT_COMMENT-ON-PR"] === "false")
        return "skipped";
    const event = JSON.parse(readFileSync(eventPath, "utf8"));
    const pullNumber = event.pull_request?.number;
    if (!pullNumber)
        return "skipped";
    const apiUrl = env.GITHUB_API_URL || "https://api.github.com";
    const commentsResponse = await fetchImpl(`${apiUrl}/repos/${repository}/issues/${pullNumber}/comments?per_page=100`, {
        headers: githubHeaders(token),
    });
    if (!commentsResponse.ok) {
        throw new Error(`failed to list PR comments: ${commentsResponse.status} ${await commentsResponse.text()}`);
    }
    const comments = (await commentsResponse.json());
    const existing = comments.find((comment) => isBotAuthored(comment.user) && comment.body?.includes(COMMENT_MARKER));
    const url = existing
        ? `${apiUrl}/repos/${repository}/issues/comments/${existing.id}`
        : `${apiUrl}/repos/${repository}/issues/${pullNumber}/comments`;
    const response = await fetchImpl(url, {
        method: existing ? "PATCH" : "POST",
        headers: githubHeaders(token),
        body: JSON.stringify({ body }),
    });
    if (!response.ok) {
        throw new Error(`failed to ${existing ? "update" : "create"} PR comment: ${response.status} ${await response.text()}`);
    }
    return existing ? "updated" : "created";
}
function githubHeaders(token) {
    return {
        authorization: `Bearer ${token}`,
        accept: "application/vnd.github+json",
        "content-type": "application/json",
        "x-github-api-version": "2022-11-28",
    };
}
function isBotAuthored(user) {
    return user?.type === "Bot" || user?.login === "github-actions[bot]";
}
function decisionLabel(state) {
    return { pass: "Passed", review: "Review recommended", fail: "Failed", blocked: "Blocked" }[state];
}
function nextAction(state) {
    return {
        pass: "No blocking action is required. Review the attached evidence before merging.",
        review: "Review the generated evidence and set a non-zero threshold when this evaluation should block merges.",
        fail: "Inspect the failing evidence, update the rubric or responses, and rerun the workflow.",
        blocked: "Resolve the runtime or configuration error shown above, then rerun the workflow.",
    }[state];
}
function formatScore(value) {
    return value === undefined ? "Unavailable" : `${(value * 100).toFixed(1)}%`;
}
function sanitizeReport(report) {
    const truncated = report.length > MAX_REPORT_CHARS ? `${report.slice(0, MAX_REPORT_CHARS)}\n\n_Report truncated._` : report;
    return truncated
        .replace(/<!--[\s\S]*?-->/g, "")
        .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "");
}
export function escapeMarkdown(value) {
    return value
        .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "")
        .replace(/([\\`*_[\]{}()#+\-.!|>])/g, "\\$1");
}
function escapeInlineCode(value) {
    return value.replace(/`/g, "\\`").replace(/[\r\n]/g, " ");
}
function escapeWorkflowData(value) {
    return value.replace(/%/g, "%25").replace(/\r/g, "%0D").replace(/\n/g, "%0A");
}
function escapeWorkflowProperty(value) {
    return escapeWorkflowData(value).replace(/:/g, "%3A").replace(/,/g, "%2C");
}
